-- ==============================================================================
-- PENYESUAIAN SKEMA UNTUK MENDUKUNG IMPOR DATA SEED
-- ==============================================================================

-- 1. Ubah GENERATED ALWAYS menjadi GENERATED BY DEFAULT
-- Hal ini memungkinkan impor ID statis dari Data Contoh Excel
-- sekaligus tetap menghasilkan ID otomatis baru saat operasional normal.
ALTER TABLE akun ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE periode ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE pengajuan ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE jurnal ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE jurnal_baris ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE audit_log ALTER COLUMN id SET GENERATED BY DEFAULT;
ALTER TABLE mutasi_bank ALTER COLUMN id SET GENERATED BY DEFAULT;

-- 2. Sesuaikan trigger immutability baris jurnal agar melarang UPDATE & DELETE pada jurnal diposting,
-- namun mengizinkan INSERT saat proses seeding.
CREATE OR REPLACE FUNCTION trg_protect_journal_lines()
RETURNS TRIGGER AS $$
DECLARE
  v_status status_jurnal;
  v_jurnal_id BIGINT;
BEGIN
  IF TG_OP = 'DELETE' THEN
    v_jurnal_id := OLD.jurnal_id;
  ELSE
    v_jurnal_id := NEW.jurnal_id;
  END IF;

  SELECT status INTO v_status FROM jurnal WHERE id = v_jurnal_id;

  -- Larang manipulasi UPDATE atau DELETE jika jurnal induk sudah diposting/dibalik (BR-04)
  IF v_status IN ('diposting', 'dibalik') AND TG_OP IN ('UPDATE', 'DELETE') THEN
    RAISE EXCEPTION 'Baris jurnal tidak dapat diubah atau dihapus karena jurnal induk berstatus %.', v_status;
  END IF;

  IF TG_OP = 'DELETE' THEN
    RETURN OLD;
  ELSE
    RETURN NEW;
  END IF;
END;
$$ LANGUAGE plpgsql;

-- 3. Kosongkan audit_log dari log auto-insert akun sementara
TRUNCATE TABLE audit_log;

-- 4. Jadikan trigger audit_akun hanya aktif AFTER UPDATE (konsisten dengan tabel lain)
DROP TRIGGER IF EXISTS audit_akun ON akun;
CREATE TRIGGER audit_akun AFTER UPDATE ON akun FOR EACH ROW EXECUTE FUNCTION trg_record_audit_log();

